    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "프롬프트 미포함 행동 생성과 코의 형태적 모핑/신장 결함은 서로 다른 내용입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "코끼리가 물을 마시는 동작 내용과 코 끝이 불규칙하게 변형 및 분리되는 물리적 결함은 서로 다른 현상입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "물을 만지고 마시는 행동 묘사와 코의 비정상적 신장 및 세그먼트 소실 결함은 대상 현상이 다릅니다."
    }
  ]
